-- cpu_top.vhd : MiniCPU-8 single-cycle core
-- Fetch:   ROM read is combinational from the PC register.
-- Execute: regfile reads async, ALU/branch logic combinational.
-- Write:   PC, register file and flags all update on the same rising edge,
--          so one instruction completes per clock cycle.
-- The program is provided as a generic (rom_t, ascending from address 0),
-- generated by tools/assembler.py.
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;
use work.minicpu_pkg.all;

entity cpu_top is
  generic (
    PROGRAM : rom_t);
  port (
    clk       : in  std_logic;
    rst       : in  std_logic;               -- synchronous, active high
    halted    : out std_logic;
    -- debug/observation ports (wires only, used by testbenches)
    dbg_pc    : out byte_t;
    dbg_flags : out std_logic_vector(3 downto 0);  -- Z N C V
    dbg_regs  : out regfile_t);
end entity cpu_top;

architecture rtl of cpu_top is
  -- All signals have a defined initial value.  This does not change the
  -- architecture, but it stops delta-cycle metavalue warnings at t=0 (before
  -- the first clock edge settles the combinational network).
  signal instr     : word_t := HALT_WORD;

  -- control
  signal reg_write, flag_write, alu_src_imm, halt_int : std_logic := '0';
  signal alu_op    : alu_op_t := ALU_ADD;
  signal branch    : branch_t := BR_NONE;

  -- datapath
  signal pc_q, pc_plus1, pc_target, br_target : byte_t := (others => '0');
  signal pc_load    : std_logic := '0';
  signal addr2      : regsel_t := (others => '0');
  signal rd1, rd2, alu_b, imm_ext, result : byte_t := (others => '0');
  signal z, c, n, v : std_logic := '0';
  signal flag_d     : std_logic_vector(3 downto 0) := (others => '0');
  signal eq         : std_logic := '0';
begin

  pc_i : entity work.pc
    port map (clk => clk, rst => rst, en => not halt_int, load => pc_load,
              target => pc_target, q => pc_q);

  rom_i : entity work.instr_rom
    generic map (INIT => PROGRAM)
    port map (addr => pc_q, data => instr);

  ctl : entity work.control_unit
    port map (opcode => instr(15 downto 12), reg_write => reg_write,
              flag_write => flag_write, alu_src_imm => alu_src_imm,
              alu_op => alu_op, branch => branch, halt => halt_int);

  -- Register file read port 2: rt field normally; for BEQ/BNE the second
  -- comparand lives in the rd field (imm6 occupies bits 5:0). See ISA.md.
  addr2 <= instr(11 downto 9) when (branch = BR_BEQ or branch = BR_BNE)
           else instr(5 downto 3);

  rf : entity work.register_file
    port map (clk => clk,
              raddr1 => instr(8 downto 6), raddr2 => addr2,
              waddr  => instr(11 downto 9), wdata  => result, we => reg_write,
              rd1 => rd1, rd2 => rd2, dbg => dbg_regs);

  -- ALU B input: register value or sign-extended imm6
  imm_ext <= std_logic_vector(resize(signed(instr(5 downto 0)), 8));
  alu_b   <= imm_ext when alu_src_imm = '1' else rd2;

  alu_i : entity work.alu
    port map (a => rd1, b => alu_b, op => alu_op,
              result => result, z => z, c => c, n => n, v => v);

  flag_d <= z & n & c & v;   -- Z N C V
  flags_i : entity work.flag_reg
    port map (clk => clk, rst => rst, en => flag_write, d => flag_d,
              q => dbg_flags);

  -- Branch condition: dedicated equality comparator (flags untouched)
  eq <= '1' when rd1 = rd2 else '0';

  -- Next-PC selection
  pc_plus1  <= std_logic_vector(unsigned(pc_q) + 1);
  br_target <= std_logic_vector(unsigned(pc_plus1) + unsigned(imm_ext));  -- mod 256

  pc_load <= '1' when (branch = BR_BEQ and eq = '1')
                  or (branch = BR_BNE and eq = '0')
                  or  branch = BR_JMP
             else '0';

  with branch select
    pc_target <= instr(7 downto 0) when BR_JMP,     -- absolute jump
                 br_target         when others;     -- PC+1+sext(imm6)

  halted <= halt_int;
  dbg_pc <= pc_q;

end architecture rtl;
